import { useId, useState, type ReactNode } from "react";
import { cn } from "@/lib/cn";

// KMP-C28 (specs/KMP-C28-setting-switch.md). A real input[type=checkbox][role=switch] inside a label.
// Not the shadcn/Radix Switch (a button): native keyboard and assistive-technology behaviour is the requirement.
// A change applies as it is made: onCheckedChange fires on every toggle. No save step, no disabled state.

export type SettingSwitchProps = {
  /** The setting name. It is the accessible name. */
  title: string;
  /** Language of the title, for Indic or mixed text. */
  titleLang?: string;
  /** Description under the toggle bar, outside the label. Supply <p> elements for several paragraphs. */
  helper?: ReactNode;
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  /** The written state; localised builds supply their own. */
  stateWords?: { on: string; off: string; lang?: string };
  className?: string;
  name?: string;
};

// the ring goes on the track while the (hidden) input has keyboard focus; the track is inside the wrapper, so target it by attribute
const ring =
  "peer-focus-visible:[&_[data-state]]:outline peer-focus-visible:[&_[data-state]]:outline-ring peer-focus-visible:[&_[data-state]]:outline-offset-ring peer-focus-visible:[&_[data-state]]:outline-focus-ring";

export function SettingSwitch({
  title,
  titleLang,
  helper,
  checked,
  defaultChecked = false,
  onCheckedChange,
  stateWords = { on: "On", off: "Off" },
  className,
  name,
}: SettingSwitchProps) {
  const [inner, setInner] = useState(defaultChecked);
  const on = checked ?? inner;
  const helperId = useId();
  const state = on ? "on" : "off";

  return (
    <div className={cn("rounded-card border-bw-default border-border-card bg-surface-raised p-inset-md", className)}>
      <label className="group relative flex min-h-control cursor-pointer flex-wrap items-center gap-x-gap-md gap-y-gap-sm">
        <input
          type="checkbox"
          role="switch"
          name={name}
          checked={on}
          onChange={(e) => {
            setInner(e.target.checked);
            onCheckedChange?.(e.target.checked);
          }}
          aria-describedby={helper ? helperId : undefined}
          className="peer sr-only [outline-style:none]"
        />
        <span lang={titleLang} className="min-w-min flex-1 basis-0 font-body text-ui-body font-medium leading-normal text-text [overflow-wrap:anywhere]">
          {title}
        </span>
        {/* Word plus track never shrink. If the title cannot keep a line beside them, the group wraps below it (D-3). */}
        <span className={cn("flex shrink-0 items-center gap-gap-md", ring)}>
        {/* Sighted users only: the native checked state already tells assistive technology. */}
        <span aria-hidden="true" lang={stateWords.lang} className="font-body text-ui-floor font-semibold leading-normal text-text">
          {on ? stateWords.on : stateWords.off}
        </span>
        <span
          aria-hidden="true"
          data-state={state}
          className={cn(
            "relative h-switch-h w-switch-w shrink-0 rounded-pill border-bw-default transition-colors duration-fast ease-standard",
            // off: open track with a real border; on: filled track, transparent border of the same width
            "data-[state=off]:border-border-strong data-[state=off]:bg-surface-raised",
            "data-[state=on]:border-transparent data-[state=on]:bg-primary",
            "group-hover:data-[state=off]:bg-surface-sunken group-active:data-[state=off]:border-primary-text group-active:data-[state=off]:bg-surface-sunken",
            "group-hover:data-[state=on]:bg-primary-hover group-active:data-[state=on]:bg-primary-active",
          )}
        >
          {/* The thumb jumps between logical start and end; it never slides. */}
          <span
            className={cn(
              "absolute inset-y-0 my-auto size-switch-thumb rounded-pill",
              on ? "end-thumb-inset bg-primary-on" : "start-thumb-inset bg-border-strong",
            )}
          />
        </span>
        </span>
      </label>
      {helper && (
        <div id={helperId} className="mt-stack-sm space-y-stack-sm font-body text-ui-reading font-regular leading-normal text-text-muted">
          {helper}
        </div>
      )}
    </div>
  );
}
